// Whirlpool – Detail-Reel 9:16. Deterministic, frame-addressed motion graphics:
// window.COMP.seek(n) puts the stage into the exact state of output frame n.
// Footage timing (cuts, slow motion) comes from timeline.js, generated by
// scripts/retime.py from edit.json; one plate per output frame.
(() => {
  const { FPS, TOTAL, SHOTS, SPEED } = window.TIMELINE;
  const params = new URLSearchParams(location.search);
  const PLATE_DIR = params.get('plates') || '../../build/whirlpool/plates';

  // One module, one text slot per section. A section starts on its cut.
  const ORDER = ['intro', 'B', 'C', 'D', 'E', 'F', 'G'];
  const START = { intro: 0, B: SHOTS.B.start, C: SHOTS.C.start, D: SHOTS.D.start, E: SHOTS.E.start, F: SHOTS.F.start, G: SHOTS.G.start };
  const END_T = TOTAL / FPS;
  const T = {
    build: 0.12,          // module builds in
    introText: 0.42,
    enter: 0.10,          // section text enters this long after its cut
    exit: 0.24,           // ...and leaves this long before the next cut
    grow: 0.60,           // end card: body grows to fit the CTA
  };
  const BODY_H = 236;

  const $ = (s, root = document) => root.querySelector(s);
  const $$ = (s, root = document) => [...root.querySelectorAll(s)];
  const clamp = (v, a = 0, b = 1) => Math.min(b, Math.max(a, v));
  const prog = (t, start, dur) => clamp((t - start) / dur);
  const lerp = (a, b, k) => a + (b - a) * k;
  const E = {
    outExpo: k => (k >= 1 ? 1 : 1 - Math.pow(2, -10 * k)),
    inExpo: k => (k <= 0 ? 0 : Math.pow(2, 10 * k - 10)),
    outCubic: k => 1 - Math.pow(1 - k, 3),
    inOutCubic: k => (k < 0.5 ? 4 * k * k * k : 1 - Math.pow(-2 * k + 2, 3) / 2),
    outBack: k => { const c1 = 1.7, c3 = c1 + 1; return 1 + c3 * Math.pow(k - 1, 3) + c1 * Math.pow(k - 1, 2); },
  };
  const show = (node, on) => { node.style.visibility = on ? 'visible' : 'hidden'; };

  // Masked line: rises in from below, leaves upwards.
  function line(span, t, tin, tout, din = 0.6, dout = 0.24) {
    const a = E.outExpo(prog(t, tin, din));
    const b = tout == null ? 0 : E.inExpo(prog(t, tout, dout));
    span.style.transform = `translateY(${((1 - a) - b) * 110}%)`;
  }
  // Block wipe left → right.
  function wipe(node, t, tin, dur = 0.55) {
    const k = E.outExpo(prog(t, tin, dur));
    show(node, k > 0);
    node.style.clipPath = `inset(-4px ${(1 - k) * 100}% -4px 0)`;
  }

  const el = {
    plate: $('#plate'), hud: $('#hud'), box: $('#box'), inner: $('#inner'), frame: $('#frame'),
    marks: $$('.mark'), logo: $('#hd img'), idx: $('#idx'), idxCol: $('#idx b span'),
    hairTop: $('#hair-top'), hairBot: $('#hair-bot'), progress: $('#progress'),
    bd: $('#bd'), slots: Object.fromEntries($$('.slot').map(s => [s.dataset.sec, s])),
    ft: $('#ft'), led: $('#led'), spd: $('#spd'), tc: $('#tc'),
    curveLine: $('#curve-line'), curveFill: $('#curve-fill'), curveHead: $('#curve-head'), curveDot: $('#curve-dot'),
    btn: $('#cta .btn'), url: $('#cta .url'), urlLine: $('#cta .url i'), arrow: $('#cta svg'),
  };

  // Speed curve of the whole edit (y: 1× at the top, 0× at the bottom).
  const CW = 230, CH = 30;
  const cx = n => (n / (TOTAL - 1)) * CW;
  const cy = v => 3 + (1 - Math.min(1, v)) * (CH - 6);
  (() => {
    let d = '';
    for (let n = 0; n < TOTAL; n += 2) d += `${n ? 'L' : 'M'}${cx(n).toFixed(1)} ${cy(SPEED[n]).toFixed(1)}`;
    el.curveLine.setAttribute('d', d);
    el.curveFill.setAttribute('d', `${d}L${CW} ${CH}L0 ${CH}Z`);
  })();

  // Index column 00…05 for the rolling counter.
  el.idxCol.innerHTML = ['00', '01', '02', '03', '04', '05'].map(s => `<span style="display:block">${s}</span>`).join('');

  const secAt = t => ORDER.reduce((cur, s) => (t >= START[s] ? s : cur), 'intro');
  const tc = t => {
    const f = Math.round(t * FPS), s = Math.floor(f / FPS);
    return [Math.floor(s / 60), s % 60, f % FPS].map(v => String(v).padStart(2, '0')).join(':');
  };

  function render(n) {
    const t = n / FPS;
    const sec = secAt(t);
    const si = ORDER.indexOf(sec);

    // ------------------------------------------------ module build-in
    const kb = E.outExpo(prog(t, T.build, 0.7));                      // box reveal, top → bottom
    const km = E.outBack(prog(t, T.build - 0.04, 0.45));              // crop marks
    el.marks.forEach(m => { m.style.transform = `scale(${km})`; m.style.opacity = clamp(km * 2).toFixed(3); });
    el.hairTop.style.transform = `scaleX(${E.outExpo(prog(t, T.build + 0.12, 0.7))})`;
    el.hairBot.style.transform = `scaleX(${E.outExpo(prog(t, T.build + 0.2, 0.7))})`;
    wipe(el.logo, t, T.build + 0.18, 0.6);
    wipe(el.idx, t, T.build + 0.3, 0.5);
    wipe(el.ft, t, T.build + 0.34, 0.6);

    // End card: body grows to fit the CTA.
    const kg = E.inOutCubic(prog(t, START.G, T.grow));
    const endH = el.slots.G.offsetHeight + 62;
    el.bd.style.height = `${lerp(BODY_H, endH, kg)}px`;
    const h = el.inner.offsetHeight;
    el.box.style.height = `${h}px`;
    el.box.style.clipPath = `inset(0 0 ${(1 - kb) * 100}% 0)`;
    el.frame.style.height = `${h}px`;

    // ------------------------------------------------ section text
    for (const s of ORDER) {
      const i = ORDER.indexOf(s);
      const tin = s === 'intro' ? T.introText : START[s] + T.enter;
      const next = ORDER[i + 1];
      const tout = next ? START[next] - T.exit : null;
      const live = t >= tin - 0.05 && (!next || t < START[next] + 0.15);
      show(el.slots[s], live);
      if (!live) continue;
      $$('.ln > span', el.slots[s]).forEach((span, j) => line(span, t, tin + j * 0.06, tout == null ? null : tout + j * 0.02));
    }

    // Rolling index 00 → 05 (intro shows 00, the end card stays on 05).
    const step = Math.min(si, 5);
    const roll = si > 0 && si <= 5 ? E.outExpo(prog(t, START[sec], 0.45)) : 1;
    el.idxCol.style.transform = `translateY(${-(step - 1 + roll) * 1.2}em)`;
    if (si === 0) el.idxCol.style.transform = 'translateY(0)';

    // Section progress (lead hair under the header).
    const nextSec = ORDER[si + 1];
    const kp = prog(t, START[sec], (nextSec ? START[nextSec] : END_T) - START[sec]);
    el.progress.style.transform = `scaleX(${t < T.build + 0.5 ? 0 : kp})`;

    // ------------------------------------------------ live readout
    const v = SPEED[n];
    const slow = v < 0.95;
    el.spd.textContent = `${v.toFixed(2)}×`;
    el.led.style.background = slow ? '#fff' : 'rgba(233, 238, 244, .2)';
    el.tc.textContent = tc(t);
    const x = cx(n);
    el.curveHead.setAttribute('x1', x); el.curveHead.setAttribute('x2', x);
    el.curveDot.setAttribute('x', x - 4); el.curveDot.setAttribute('y', cy(v) - 4);
    el.curveFill.style.clipPath = `inset(0 ${CW - x}px 0 0)`;

    // ------------------------------------------------ end card CTA
    const g = START.G;
    wipe(el.btn, t, g + 0.55, 0.6);
    const ku = E.outExpo(prog(t, g + 0.75, 0.6));
    el.url.style.opacity = ku.toFixed(3);
    el.url.style.transform = `translateX(${(1 - ku) * -20}px)`;
    el.urlLine.style.transform = `scaleX(${E.outExpo(prog(t, g + 0.95, 0.7))})`;
    const nudge = t > g + 1.4 ? Math.pow(Math.sin(Math.PI * (((t - g - 1.4) % 1.0) / 1.0)), 2) : 0;
    el.arrow.style.transform = `translateX(${nudge * 7}px)`;
  }

  async function seek(n) {
    const idx = String(Math.min(n, TOTAL - 1)).padStart(4, '0');
    if (el.plate.dataset.idx !== idx) {
      el.plate.src = `${PLATE_DIR}/f${idx}.jpg`;
      await el.plate.decode();
      el.plate.dataset.idx = idx;
    }
    render(n);
  }

  async function init() {
    await Promise.all([400, 500, 600, 700].map(w => document.fonts.load(`${w} 40px Poppins`)));
    await document.fonts.ready;
    await el.logo.decode();
    const t0 = params.get('t');
    await seek(t0 ? Math.round(parseFloat(t0) * FPS) : 0);
  }

  window.COMP = { FPS, TOTAL, seek, ready: init() };
})();
